// Finds every lead due for a follow up today.
// Days to wait after the last contact, based on how many attempts were made:
// 0 attempts = today, 1 = 2 days, 2 = 2 days, 3 = 3 days, 4 = 7 days, 5+ = every 14 days.
const GAPS = [0, 2, 2, 3, 7];
const SKIP = ['closed', 'do not contact', 'dead'];
const TEMP_ORDER = { hot: 0, warm: 1, cold: 2 };
const today = new Date(); today.setHours(0, 0, 0, 0);
const due = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.Name) continue;
  if (SKIP.includes(String(r.Status || '').trim().toLowerCase())) continue;
  const attempts = parseInt(r.Attempts || 0, 10) || 0;
  const gap = attempts < GAPS.length ? GAPS[attempts] : 14;
  let dueDate = today;
  if (r['Last Contact']) {
    const d = new Date(r['Last Contact']);
    if (!isNaN(d)) { d.setHours(0, 0, 0, 0); dueDate = new Date(d.getTime() + gap * 86400000); }
  }
  if (dueDate <= today) {
    due.push({ json: { ...r, attempts, overdueDays: Math.round((today - dueDate) / 86400000) } });
  }
}
due.sort((a, b) => (TEMP_ORDER[String(a.json.Temperature).toLowerCase()] ?? 3) - (TEMP_ORDER[String(b.json.Temperature).toLowerCase()] ?? 3));
return due;

parameters.text:
=You are Sales Cheat Code, writing the next follow up text for a mortgage loan officer. Reply with ONLY the text message, nothing else.

Rules for the text:
1. Under 300 characters, sounds like a real person, not a script.
2. End with a two option close, for example "Does today at 4 or tomorrow at 10 work better?"
3. Say "home" or "your home options" instead of "mortgage", "loan", or "refinance".
4. Never mention a rate, payment, approval, or savings amount. Never say "guaranteed", "pre approved", or "lowest".
5. Change the angle based on attempts: 0 to 1 attempts, friendly check in; 2 to 3, give a reason to talk now; 4 or more, a light pattern interrupt such as asking if they want you to close their file.

Lead name: {{ $json.Name }}
Stage: {{ $json.Stage }}
Temperature: {{ $json.Temperature }}
Follow up attempts so far: {{ $json.attempts }}
Last contact: {{ $json['Last Contact'] }}
Notes: {{ $json.Notes }}

