// Builds one email with every lead due today and its drafted text.
const leads = $('Find leads due today').all().map(i => i.json);
const texts = $input.all().map(i => (i.json.text || '').trim());
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const color = t => ({ hot: '#b3261e', warm: '#a15c07', cold: '#3b5b8a' }[String(t).toLowerCase()] || '#555');
const rows = leads.map((l, i) => `
  <tr><td style="padding:14px 0;border-bottom:1px solid #e3e6eb">
    <div style="font-size:16px;font-weight:700">${esc(l.Name)}
      <span style="font-size:12px;color:${color(l.Temperature)};margin-left:6px">${esc(l.Temperature)}</span></div>
    <div style="font-size:13px;color:#555">${esc(l.Phone)} · ${esc(l.Stage)} · attempt ${l.attempts + 1}${l.overdueDays > 0 ? ` · <b>${l.overdueDays} days overdue</b>` : ''}</div>
    <div style="margin-top:8px;padding:10px 12px;background:#f3f5f8;border-radius:6px;font-size:14px">${esc(texts[i])}</div>
  </td></tr>`).join('');
const html = `<div style="font-family:Arial,sans-serif;max-width:620px;color:#13233f">
  <h2 style="margin:0 0 4px">Your follow ups for today</h2>
  <p style="margin:0 0 10px;color:#555">${leads.length} leads due, hottest first. After you text someone, update their Last Contact and Attempts in the sheet.</p>
  <table style="width:100%;border-collapse:collapse">${rows}</table></div>`;
return [{ json: { subject: `Sales Cheat Code: ${leads.length} follow ups due today`, html } }];
